    export const getPartnerEarningsUrl = (rid: string,
    params: PartnerEarningsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/partner/restaurants/${rid}/earnings?${stringifiedParams}` : `/partner/restaurants/${rid}/earnings`
}

